(() => {
  let videoFile = null;
  let pressFrame = null;
  let reactionFrame = null;

  const dropzone = document.getElementById('sm-dropzone');
  const fileInput = document.getElementById('sm-file-input');
  const browseBtn = document.getElementById('sm-browse-btn');
  const workspace = document.getElementById('sm-workspace');
  const videoEl = document.getElementById('sm-video-el');
  const fpsSelect = document.getElementById('sm-fps-select');

  const currentFrameEl = document.getElementById('sm-current-frame-num');
  const currentTimeEl = document.getElementById('sm-current-time-str');
  const pressFrameEl = document.getElementById('sm-press-frame-val');
  const pressTimeEl = document.getElementById('sm-press-time-val');
  const reactionFrameEl = document.getElementById('sm-reaction-frame-val');
  const reactionTimeEl = document.getElementById('sm-reaction-time-val');
  const latencyValEl = document.getElementById('sm-total-latency-val');
  const jitterValEl = document.getElementById('sm-jitter-val');

  const playPauseBtn = document.getElementById('sm-play-pause-btn');
  const stepBack1 = document.getElementById('sm-step-back-1');
  const stepFwd1 = document.getElementById('sm-step-fwd-1');
  const stepBack5 = document.getElementById('sm-step-back-5');
  const stepFwd5 = document.getElementById('sm-step-fwd-5');
  const markPressBtn = document.getElementById('sm-mark-press-btn');
  const markReactionBtn = document.getElementById('sm-mark-reaction-btn');
  const copyReportBtn = document.getElementById('sm-copy-report-btn');

  function getFps() {
    return parseFloat(fpsSelect.value) || 240;
  }

  function getCurrentFrame() {
    const fps = getFps();
    return Math.round(videoEl.currentTime * fps);
  }

  function seekFrame(frameDelta) {
    videoEl.pause();
    playPauseBtn.textContent = 'Play';
    const fps = getFps();
    const frameTime = 1 / fps;
    const targetTime = Math.max(0, Math.min(videoEl.duration, videoEl.currentTime + frameDelta * frameTime));
    videoEl.currentTime = targetTime;
  }

  function updateHud() {
    const curFrame = getCurrentFrame();
    currentFrameEl.textContent = String(curFrame);
    currentTimeEl.textContent = videoEl.currentTime.toFixed(3) + 's';
  }

  function calculate() {
    if (pressFrame === null || reactionFrame === null) return;
    const fps = getFps();
    const deltaFrames = Math.max(0, reactionFrame - pressFrame);
    const ms = (deltaFrames / fps) * 1000;
    const frameIntervalMs = 1000 / fps;
    const tolerance = frameIntervalMs / 2;

    latencyValEl.textContent = ms.toFixed(1);
    jitterValEl.textContent = `Tolerance: ±${tolerance.toFixed(1)} ms (${deltaFrames} frames elapsed)`;
  }

  function handleFile(file) {
    if (!file) return;
    videoFile = file;
    const url = URL.createObjectURL(file);
    videoEl.src = url;
    dropzone.classList.add('hidden');
    workspace.classList.remove('hidden');
    videoEl.addEventListener('loadedmetadata', () => {
      videoEl.currentTime = 0;
      updateHud();
    });
  }

  browseBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    fileInput.click();
  });
  dropzone.addEventListener('click', () => fileInput.click());
  fileInput.addEventListener('change', () => {
    if (fileInput.files && fileInput.files[0]) handleFile(fileInput.files[0]);
  });

  dropzone.addEventListener('dragover', (e) => e.preventDefault());
  dropzone.addEventListener('drop', (e) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) handleFile(e.dataTransfer.files[0]);
  });

  videoEl.addEventListener('timeupdate', updateHud);
  videoEl.addEventListener('seeked', updateHud);

  playPauseBtn.addEventListener('click', () => {
    if (videoEl.paused) {
      videoEl.play();
      playPauseBtn.textContent = 'Pause';
    } else {
      videoEl.pause();
      playPauseBtn.textContent = 'Play';
    }
  });

  stepBack1.addEventListener('click', () => seekFrame(-1));
  stepFwd1.addEventListener('click', () => seekFrame(1));
  stepBack5.addEventListener('click', () => seekFrame(-5));
  stepFwd5.addEventListener('click', () => seekFrame(5));
  fpsSelect.addEventListener('change', calculate);

  markPressBtn.addEventListener('click', () => {
    pressFrame = getCurrentFrame();
    pressFrameEl.textContent = String(pressFrame);
    pressTimeEl.textContent = `Time: ${(videoEl.currentTime * 1000).toFixed(1)} ms`;
    calculate();
  });

  markReactionBtn.addEventListener('click', () => {
    reactionFrame = getCurrentFrame();
    reactionFrameEl.textContent = String(reactionFrame);
    reactionTimeEl.textContent = `Time: ${(videoEl.currentTime * 1000).toFixed(1)} ms`;
    calculate();
  });

  copyReportBtn.addEventListener('click', () => {
    if (pressFrame === null || reactionFrame === null) {
      alert('Please mark both Button Actuation and Screen Reaction frames first.');
      return;
    }
    const fps = getFps();
    const deltaFrames = Math.max(0, reactionFrame - pressFrame);
    const ms = (deltaFrames / fps) * 1000;
    const report = [
      '=== ToolkitGen Optical Input Lag Report ===',
      `Date: ${new Date().toISOString().split('T')[0]}`,
      `Camera Frame Rate: ${fps} FPS`,
      `Actuation Frame: ${pressFrame}`,
      `Reaction Frame: ${reactionFrame}`,
      `Elapsed Frames: ${deltaFrames}`,
      `Calculated Latency: ${ms.toFixed(1)} ms (±${(1000 / fps / 2).toFixed(1)} ms)`,
      'Diagnostic URL: https://toolkitgen.com/tool/slowmo_latency_meter',
    ].join('\n');

    if (navigator.clipboard) {
      navigator.clipboard.writeText(report).then(() => alert('Optical latency report copied!'));
    } else {
      prompt('Copy your report:', report);
    }
  });
})();
